extends Node
@export_range(1, 600) var maximum_samples: int = 600:
    set(value):
        maximum_samples = clampi(value, 1, 600)
var samples: Array[Dictionary] = []
var collecting := false
var finished := false
func begin() -> void:
    maximum_samples = clampi(maximum_samples, 1, 600)
    samples.clear()
    collecting = true
    finished = false
func _process(delta: float) -> void:
    if not collecting or finished:
        return
    samples.append({"frame": samples.size(), "delta_ms": delta * 1000.0, "process_ms": Performance.get_monitor(Performance.TIME_PROCESS) * 1000.0, "physics_ms": Performance.get_monitor(Performance.TIME_PHYSICS_PROCESS) * 1000.0, "draw_calls": Performance.get_monitor(Performance.RENDER_TOTAL_DRAW_CALLS_IN_FRAME)})
    if samples.size() >= maximum_samples:
        collecting = false
        finished = true
func save_csv(destination: String) -> Error:
    if collecting or not finished:
        return ERR_BUSY
    if not destination.begins_with("user://"):
        return ERR_INVALID_PARAMETER
    var file := FileAccess.open(destination, FileAccess.WRITE)
    if file == null:
        return FileAccess.get_open_error()
    file.store_csv_line(PackedStringArray(["frame", "delta_ms", "process_ms", "physics_ms", "draw_calls"]))
    for row in samples:
        file.store_csv_line(PackedStringArray([str(row.frame), str(row.delta_ms), str(row.process_ms), str(row.physics_ms), str(row.draw_calls)]))
    file.flush()
    var err := file.get_error()
    file.close()
    return err
